### Code Examples

```
// Create a 16 bytes ArrayBuffer
const buffer = new ArrayBuffer(16);
// Create a new DataView
const view = new DataView(buffer);
// Get lengths and offset
let len1 = buffer.byteLength);
let len2 = view.byteLength;
let off1 = view.byteOffset;

---

// Create a 16 bytes ArrayBuffer
const buffer = new ArrayBuffer(16);
// Create a new DataView
const view = new DataView(buffer, 4, 8);
// Get lengths and offset
let len1 = buffer.byteLength);
let len2 = view.byteLength;
let off1 = view.byteOffset;

---

const buffer = new ArrayBuffer(8);
const view = new DataView(buffer);
// Write a 32-bit signed integer at byte offset 0
view.setInt32(0, 123456);
// Read it back
const value = view.getInt32(0);
console.log(value); // 123456

---

const buffer = new ArrayBuffer(16);
const view = new DataView(buffer);
view.setFloat64(0, Math.PI);
view.setFloat64(8, Math.E);
const pi = view.getFloat64(0);
const e  = view.getFloat64(8);
console.log("PI:", pi);
console.log("E:", e);

---

const buffer = new ArrayBuffer(4);
const view   = new DataView(buffer);
// Same number, two different byte orders:
view.setUint32(0, 0x12345678, true);  // little-endian
console.log(new Uint8Array(buffer));
// Example output: Uint8Array(4) [120, 86, 52, 18] (0x78, 0x56, 0x34, 0x12)
// Overwrite with big-endian
view.setUint32(0, 0x12345678, false); // big-endian
console.log(new Uint8Array(buffer));
// Example output: Uint8Array(4) [18, 52, 86, 120] (0x12, 0x34, 0x56, 0x78)

---

const buffer = new ArrayBuffer(12);
const view   = new DataView(buffer);
// Byte 0: a flag (0 or 1)
view.setUint8(0, 1);
// Bytes 1-2: a 16-bit length (little-endian)
view.setUint16(1, 500, true);
// Bytes 4-11: a 64-bit float (skip byte 3 for alignment)
view.setFloat64(4, 3.14159, true);
// Read the values back
const flag   = view.getUint8(0);
const length = view.getUint16(1, true);
const value  = view.getFloat64(4, true);
console.log("Flag:", flag);
console.log("Length:", length);
console.log("Value:", value);
```

## Tutorials

When multiple threads (for example, the main thread and one or more workers)
access the same data, you can getrace conditions. Atomics helps avoid
these race conditions by providing operations that:Work on shared typed arraysAre performed atomically (cannot be interrupted halfway)Return the previous value of the elementTheAtomicsobject is a global object (likeMath)
with static methods such asAtomics.load(),Atomics.store(),Atomics.add(), and more.Atomics are an advanced feature.You typically use Atomics when you work with:Web WorkersWorker ThreadsShared memoryRequirementsTo use Atomics you need:ASharedArrayBufferA typed array that uses the shared buffer (e.g.Int32Array)One or more workers (or threads) that share the same bufferSecurity:Browsers may require special headers (like COOP/COEP) forSharedArrayBufferto be enabled on the web.Basic Atomics UsageExample: Creating a Shared Typed ArrayCreate a shared buffer and a shared integer array:const buffer = new SharedArrayBuffer(4 * Int32Array.BYTES_PER_ELEMENT);// Shared integer array with 4 elementsconst sharedArray = new Int32Array(buffer);// Initialize the arraysharedArray[0] = 10;sharedArray[1] = 20;sharedArray[2] = 30;sharedArray[3] = 40;Try it Yourself »Atomic Read and WriteUseAtomics.load()toreadandAtomics.store()towritean element in a sharedtyped array.Example: Atomics.load() and Atomics.store()var buffer = new SharedArrayBuffer(4 * Int32Array.BYTES_PER_ELEMENT);var sharedArray = new Int32Array(buffer);// Store a value atomicallyAtomics.store(sharedArray, 0, 123);// Load the value atomicallyvar value = Atomics.load(sharedArray, 0);console.log("Value:", value); // Value: 123Atomics.store()returns the value you stored.Atomics.load()returns the current value of the element.Atomic Add and SubtractAtomics.add()andAtomics.sub()change a value and
  return theoldvalue.Example: Atomics.add()var buffer = new SharedArrayBuffer(4 * Int32Array.BYTES_PER_ELEMENT);var sharedArray = new Int32Array(buffer);sharedArray[0] = 5;var oldValue = Atomics.add(sharedArray, 0, 3);console.log("Old:", oldValue);  // Old: 5console.log("New:", sharedArray[0]);// New: 8Example: Atomics.sub()var buffer = new SharedArrayBuffer(4 * Int32Array.BYTES_PER_ELEMENT);var sharedArray = new Int32Array(buffer);sharedArray[0] = 10;var oldValue = Atomics.sub(sharedArray, 0, 4);console.log("Old:", oldValue);  // Old: 10console.log("New:", sharedArray[0]);// New: 6Atomic Exchange and CompareExchangeAtomics.exchange()sets a new value and returns the old one.Atomics.compareExchange()only sets a new value if the current
value is equal to a given expected value.Example: Atomics.exchange()var buffer = new SharedArrayBuffer(4 * Int32Array.BYTES_PER_ELEMENT);var sharedArray = new Int32Array(buffer);sharedArray[0] = 1;var oldValue = Atomics.exchange(sharedArray, 0, 99);console.log("Old:", oldValue);   // Old: 1console.log("New:", sharedArray[0]); // New: 99Example: Atomics.compareExchange()var buffer = new SharedArrayBuffer(4 * Int32Array.BYTES_PER_ELEMENT);var sharedArray = new Int32Array(buffer);sharedArray[0] = 10;// Only replace 10 with 20 if the current value is 10var oldValue = Atomics.compareExchange(sharedArray, 0, 10, 20);console.log("Old:", oldValue);   // Old: 10console.log("New:", sharedArray[0]); // New: 20// Now it will NOT change because the expected value does not matcholdValue = Atomics.compareExchange(sharedArray, 0, 10, 30);console.log("Old:", oldValue);   // Old: 20console.log("New:", sharedArray[0]); // New: 20Atomics.wait() and Atomics.notify()Atomics.wait()(in workers) can put a thread to sleep until the
value at a position changes, andAtomics.notify()wakes up one
or more sleeping threads.Important:Atomics.wait()can only be used in
worker contexts (not on the main thread) in browsers.Example: Worker Waiting for a ValueMain thread (simplified):// main.jsvar buffer = new SharedArrayBuffer(4);var sharedArray = new Int32Array(buffer);sharedArray[0] = 0;var worker = new Worker("worker.js");// Send the shared buffer to the workerworker.postMessage(buffer);// Simulate some work, then set the value and notify the workersetTimeout(function() {Atomics.store(sharedArray, 0, 1);Atomics.notify(sharedArray, 0, 1); // wake 1 worker}, 1000);Worker (worker.js):// worker.jsonmessage = function(e) {var buffer = e.data;var sharedArray = new Int32Array(buffer);console.log("Worker waiting...");var result = Atomics.wait(sharedArray, 0, 0); // wait while value is 0console.log("Worker woken, result =", result);console.log("New value:", Atomics.load(sharedArray, 0));};Complete Atomics ReferenceRevised December 2025MethodDescriptionload(typedArray, index)Reads and returns the value at index.store(typedArray, index, value)Stores value at index and returns it.add(typedArray, index, value)Adds value to the element and returns the old value.sub(typedArray, index, value)Subtracts value and returns the old value.and(typedArray, index, value)Performs bitwise AND with value and returns the old value.or(typedArray, index, value)Performs bitwise OR with value and returns the old value.xor(typedArray, index, value)Performs bitwise XOR with value and returns the old value.exchange(typedArray, index, value)Replaces the value at index and returns the old value.compareExchange(typedArray, index, expected, value)Replaces the value at index with value if the
current value is expected. Returns the old value.wait(typedArray, index, value, timeout?)(Worker only) Blocks the calling thread until the element changes or timeout.notify(typedArray, index, count)Wakes up sleeping threads that are waiting on index.Atomics are for communication between threads using shared memoryYou use them with SharedArrayBuffer and Typed ArraysAtomics operations can not be interrupted by other threadsUse Atomics only when you need low-level synchronizationMost JavaScript code does not need AtomicsLearn More:Typed Array TutorialTyped Array MethodsTyped Array ReferenceArray BuffersDataViews❮ PreviousNext ❯★+1Sign in to track progress

### Code Examples

```
const buffer = new SharedArrayBuffer(4 * Int32Array.BYTES_PER_ELEMENT);
// Shared integer array with 4 elements
const sharedArray = new Int32Array(buffer);
// Initialize the array
sharedArray[0] = 10;
sharedArray[1] = 20;
sharedArray[2] = 30;
sharedArray[3] = 40;

---

var buffer = new SharedArrayBuffer(4 * Int32Array.BYTES_PER_ELEMENT);
var sharedArray = new Int32Array(buffer);
// Store a value atomically
Atomics.store(sharedArray, 0, 123);
// Load the value atomically
var value = Atomics.load(sharedArray, 0);
console.log("Value:", value); // Value: 123

---

var buffer = new SharedArrayBuffer(4 * Int32Array.BYTES_PER_ELEMENT);
var sharedArray = new Int32Array(buffer);
sharedArray[0] = 5;
var oldValue = Atomics.add(sharedArray, 0, 3);
console.log("Old:", oldValue);  // Old: 5
console.log("New:", sharedArray[0]);// New: 8

---

var buffer = new SharedArrayBuffer(4 * Int32Array.BYTES_PER_ELEMENT);
var sharedArray = new Int32Array(buffer);
sharedArray[0] = 10;
var oldValue = Atomics.sub(sharedArray, 0, 4);
console.log("Old:", oldValue);  // Old: 10
console.log("New:", sharedArray[0]);// New: 6

---

var buffer = new SharedArrayBuffer(4 * Int32Array.BYTES_PER_ELEMENT);
var sharedArray = new Int32Array(buffer);
sharedArray[0] = 1;
var oldValue = Atomics.exchange(sharedArray, 0, 99);
console.log("Old:", oldValue);   // Old: 1
console.log("New:", sharedArray[0]); // New: 99

---

var buffer = new SharedArrayBuffer(4 * Int32Array.BYTES_PER_ELEMENT);
var sharedArray = new Int32Array(buffer);
sharedArray[0] = 10;
// Only replace 10 with 20 if the current value is 10
var oldValue = Atomics.compareExchange(sharedArray, 0, 10, 20);
console.log("Old:", oldValue);   // Old: 10
console.log("New:", sharedArray[0]); // New: 20
// Now it will NOT change because the expected value does not match
oldValue = Atomics.compareExchange(sharedArray, 0, 10, 30);
console.log("Old:", oldValue);   // Old: 20
console.log("New:", sharedArray[0]); // New: 20

---

// main.js
var buffer = new SharedArrayBuffer(4);
var sharedArray = new Int32Array(buffer);
sharedArray[0] = 0;
var worker = new Worker("worker.js");
// Send the shared buffer to the worker
worker.postMessage(buffer);
// Simulate some work, then set the value and notify the worker
setTimeout(function() {
Atomics.store(sharedArray, 0, 1);
Atomics.notify(sharedArray, 0, 1); // wake 1 worker
}, 1000);

---

// worker.js
onmessage = function(e) {
var buffer = e.data;
var sharedArray = new Int32Array(buffer);
console.log("Worker waiting...");
var result = Atomics.wait(sharedArray, 0, 0); // wait while value is 0
console.log("Worker woken, result =", result);
console.log("New value:", Atomics.load(sharedArray, 0));
};
```

